package net.civeira.phylax.features.access.userinvitation.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class EmailVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property email of user invitation ")
  void test_email_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> EmailVO.tryFrom(null));
    Assertions.assertEquals("one", EmailVO.from("one").getEmail());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> EmailVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", EmailVO.from("one").toString());
  }
}
